import Foundation
import CryptoKit

// Payment Processing CLI Tool with Audit Logging
// Version 2.4.1 - Enterprise Edition

struct AuditEntry: Codable {
    let timestamp: Date
    let action: String
    let userId: String
    let amount: Decimal
    let status: String
    let checksum: String
}

class AuditLogger {
    private let logFile: String
    private var entries: [AuditEntry] = []
    private let hmacKey: SymmetricKey

    init(logFile: String = "/var/log/payments/audit.log") {
        self.logFile = logFile
        // Load HMAC key from environment; require it to be configured for audit integrity.
        // Falls back to a randomly generated in-memory key if not provided (checksums still
        // cannot be forged by an external attacker without the key material).
        if let keyEnv = ProcessInfo.processInfo.environment["AUDIT_HMAC_KEY"],
           let keyData = Data(base64Encoded: keyEnv), keyData.count >= 32 {
            self.hmacKey = SymmetricKey(data: keyData)
        } else {
            self.hmacKey = SymmetricKey(size: .bits256)
        }
    }

    func log(action: String, userId: String, amount: Decimal, status: String) {
        let entry = AuditEntry(
            timestamp: Date(),
            action: action,
            userId: userId,
            amount: amount,
            status: status,
            checksum: computeChecksum(action: action, userId: userId, amount: amount)
        )
        entries.append(entry)
        persistEntry(entry)
    }

    private func computeChecksum(action: String, userId: String, amount: Decimal) -> String {
        let data = "\(action)|\(userId)|\(amount)".data(using: .utf8)!
        let mac = HMAC<SHA256>.authenticationCode(for: data, using: hmacKey)
        return mac.map { String(format: "%02x", $0) }.joined()
    }

    private func persistEntry(_ entry: AuditEntry) {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        guard let data = try? encoder.encode(entry),
              let line = String(data: data, encoding: .utf8) else { return }
        let handle = FileHandle(forWritingAtPath: logFile)
        handle?.seekToEndOfFile()
        handle?.write((line + "\n").data(using: .utf8)!)
        handle?.closeFile()
    }
}

struct PaymentRequest {
    let userId: String
    let merchantId: String
    let amount: Decimal
    let currency: String
    let idempotencyKey: String
}

class BalanceManager {
    private var balances: [String: Decimal] = [:]
    private let lock = NSLock()

    func getBalance(userId: String) -> Decimal {
        lock.lock()
        defer { lock.unlock() }
        return balances[userId] ?? Decimal(0)
    }

    func credit(userId: String, amount: Decimal) {
        lock.lock()
        defer { lock.unlock() }
        balances[userId, default: Decimal(0)] += amount
    }

    func debit(userId: String, amount: Decimal) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        let current = balances[userId] ?? Decimal(0)
        if current >= amount {
            balances[userId] = current - amount
            return true
        }
        return false
    }
}

class PaymentProcessor {
    private let balanceManager: BalanceManager
    private let auditLogger: AuditLogger
    private var processedKeys: Set<String> = []
    private let keyLock = NSLock()

    init(balanceManager: BalanceManager, auditLogger: AuditLogger) {
        self.balanceManager = balanceManager
        self.auditLogger = auditLogger
    }

    func processPayment(_ request: PaymentRequest) -> (success: Bool, message: String) {
        // Validate request
        guard !request.userId.isEmpty, !request.merchantId.isEmpty else {
            auditLogger.log(action: "PAYMENT_REJECTED", userId: request.userId, amount: request.amount, status: "INVALID_REQUEST")
            return (false, "Invalid request parameters")
        }

        guard request.amount > Decimal(0) else {
            auditLogger.log(action: "PAYMENT_REJECTED", userId: request.userId, amount: request.amount, status: "INVALID_AMOUNT")
            return (false, "Amount must be positive")
        }

        // Idempotency check
        keyLock.lock()
        let isDuplicate = processedKeys.contains(request.idempotencyKey)
        if !isDuplicate {
            processedKeys.insert(request.idempotencyKey)
        }
        keyLock.unlock()

        if isDuplicate {
            auditLogger.log(action: "PAYMENT_DUPLICATE", userId: request.userId, amount: request.amount, status: "IDEMPOTENT_REJECT")
            return (false, "Duplicate payment request")
        }

        // Apply fee calculation
        let totalAmount = calculateTotalWithFees(request: request)

        // Process debit
        let debitSuccess = balanceManager.debit(userId: request.userId, amount: totalAmount)

        if debitSuccess {
            // Credit merchant
            balanceManager.credit(userId: request.merchantId, amount: request.amount)
            auditLogger.log(action: "PAYMENT_SUCCESS", userId: request.userId, amount: totalAmount, status: "COMPLETED")
            return (true, "Payment of \(request.amount) \(request.currency) processed successfully")
        } else {
            auditLogger.log(action: "PAYMENT_FAILED", userId: request.userId, amount: totalAmount, status: "INSUFFICIENT_FUNDS")
            return (false, "Insufficient funds")
        }
    }

    private func calculateTotalWithFees(request: PaymentRequest) -> Decimal {
        let baseFeeRate: Decimal = Decimal(string: "0.029")!  // 2.9%
        let fixedFee: Decimal = Decimal(string: "0.30")!      // $0.30

        // Apply currency-specific fee adjustments
        let currencyMultiplier: Decimal
        switch request.currency.uppercased() {
        case "USD": currencyMultiplier = Decimal(1)
        case "EUR": currencyMultiplier = Decimal(string: "1.01")!
        case "GBP": currencyMultiplier = Decimal(string: "1.02")!
        default: currencyMultiplier = Decimal(string: "1.05")!
        }

        let fee = (request.amount * baseFeeRate + fixedFee) * currencyMultiplier
        let roundedFee = roundToTwoDecimals(fee)

        return request.amount + roundedFee
    }

    private func roundToTwoDecimals(_ value: Decimal) -> Decimal {
        var result = Decimal()
        var mutableValue = value
        NSDecimalRound(&result, &mutableValue, 2, .bankers)
        return result
    }
}

class RefundProcessor {
    private let balanceManager: BalanceManager
    private let auditLogger: AuditLogger
    private var refundedTransactions: Set<String> = []
    private let refundLock = NSLock()

    init(balanceManager: BalanceManager, auditLogger: AuditLogger) {
        self.balanceManager = balanceManager
        self.auditLogger = auditLogger
    }

    func processRefund(transactionId: String, userId: String, merchantId: String, originalAmount: Decimal, refundAmount: Decimal) -> (success: Bool, message: String) {

        guard refundAmount > Decimal(0) else {
            auditLogger.log(action: "REFUND_REJECTED", userId: userId, amount: refundAmount, status: "INVALID_AMOUNT")
            return (false, "Refund amount must be positive")
        }

        // Check refund doesn't exceed original amount
        guard refundAmount <= originalAmount else {
            auditLogger.log(action: "REFUND_REJECTED", userId: userId, amount: refundAmount, status: "EXCEEDS_ORIGINAL")
            return (false, "Refund exceeds original transaction amount")
        }

        // Prevent double refund
        refundLock.lock()
        let alreadyRefunded = refundedTransactions.contains(transactionId)
        if !alreadyRefunded {
            refundedTransactions.insert(transactionId)
        }
        refundLock.unlock()

        if alreadyRefunded {
            auditLogger.log(action: "REFUND_DUPLICATE", userId: userId, amount: refundAmount, status: "ALREADY_REFUNDED")
            return (false, "Transaction already refunded")
        }

        // Debit merchant and credit user
        let merchantDebit = balanceManager.debit(userId: merchantId, amount: refundAmount)
        if merchantDebit {
            balanceManager.credit(userId: userId, amount: refundAmount)
            auditLogger.log(action: "REFUND_SUCCESS", userId: userId, amount: refundAmount, status: "COMPLETED")
            return (true, "Refund of \(refundAmount) processed")
        } else {
            // Rollback the refund tracking
            refundLock.lock()
            refundedTransactions.remove(transactionId)
            refundLock.unlock()
            auditLogger.log(action: "REFUND_FAILED", userId: userId, amount: refundAmount, status: "MERCHANT_INSUFFICIENT")
            return (false, "Merchant has insufficient funds for refund")
        }
    }
}

// CLI Entry Point
func main() {
    let balanceManager = BalanceManager()
    let auditLogger = AuditLogger()
    let paymentProcessor = PaymentProcessor(balanceManager: balanceManager, auditLogger: auditLogger)
    let refundProcessor = RefundProcessor(balanceManager: balanceManager, auditLogger: auditLogger)

    // Initialize test balances
    balanceManager.credit(userId: "user_001", amount: Decimal(1000))
    balanceManager.credit(userId: "merchant_001", amount: Decimal(5000))

    let args = CommandLine.arguments
    guard args.count > 1 else {
        print("Usage: payment-cli [pay|refund|balance]")
        return
    }

    switch args[1] {
    case "pay":
        guard args.count >= 6 else {
            print("Usage: payment-cli pay <userId> <merchantId> <amount> <currency> [idempotencyKey]")
            return
        }
        let key = args.count > 6 ? args[6] : UUID().uuidString
        let request = PaymentRequest(
            userId: args[2],
            merchantId: args[3],
            amount: Decimal(string: args[4]) ?? Decimal(0),
            currency: args[5],
            idempotencyKey: key
        )
        let result = paymentProcessor.processPayment(request)
        print(result.message)

    case "refund":
        guard args.count >= 7 else {
            print("Usage: payment-cli refund <transactionId> <userId> <merchantId> <originalAmount> <refundAmount>")
            return
        }
        let result = refundProcessor.processRefund(
            transactionId: args[2],
            userId: args[3],
            merchantId: args[4],
            originalAmount: Decimal(string: args[5]) ?? Decimal(0),
            refundAmount: Decimal(string: args[6]) ?? Decimal(0)
        )
        print(result.message)

    case "balance":
        guard args.count >= 3 else {
            print("Usage: payment-cli balance <userId>")
            return
        }
        let balance = balanceManager.getBalance(userId: args[2])
        print("Balance for \(args[2]): \(balance)")

    default:
        print("Unknown command: \(args[1])")
    }
}

main()
